import type {EntryPointProps} from 'react-relay'

import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import {getFavoriteProjectsHref} from '../../../../routes'
import Redirect from '../../../common/Redirect/Redirect'
import type {WelcomeScreenHasPipelinesQuery} from '../components/WelcomeScreen/__generated__/WelcomeScreenHasPipelinesQuery.graphql'
import WelcomeScreen from '../components/WelcomeScreen/WelcomeScreen'
import {useHasPipelines} from '../components/WelcomeScreen/WelcomeScreen.hooks'
import {getWelcomePipelinesPageHref} from '../PipelinesPages.utils'
import {isPipelinesEnabledInExclusiveMode} from '../utils/featureToggles'

type Queries = {hasPipelines: WelcomeScreenHasPipelinesQuery}

function IndexPage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  useDocumentTitle('TeamCity Pipelines')

  const hasPipelines = useHasPipelines(queries.hasPipelines)

  if (!hasPipelines) {
    return <Redirect to={getWelcomePipelinesPageHref()} replace />
  }
  if (!isPipelinesEnabledInExclusiveMode()) {
    return <Redirect to={getFavoriteProjectsHref()} replace />
  }

  return <WelcomeScreen hasPipelines />
}
export type IndexPageComponent = typeof IndexPage
export default IndexPage
